ALTER TABLE moodle_connections ADD baseline_at DATETIME(3) NULL, ADD monitoring_opt_in BOOLEAN NOT NULL DEFAULT FALSE, ADD retry_count TINYINT UNSIGNED NOT NULL DEFAULT 0, ADD notification_categories JSON NULL;
ALTER TABLE student_notifications MODIFY type ENUM('TASK_UPCOMING','TASK_OVERDUE','EVENT_REMINDER','POMODORO_COMPLETED','GENERAL_REMINDER','ACHIEVEMENT','STREAK_MILESTONE','MOODLE_ANNOUNCEMENT','MOODLE_DEADLINE','MOODLE_NEW_ITEM') NOT NULL;
CREATE TABLE push_subscriptions (
 id CHAR(36) CHARACTER SET ascii PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,endpoint_hash CHAR(64) CHARACTER SET ascii NOT NULL UNIQUE,
 subscription_cipher TEXT NOT NULL,device_label VARCHAR(80) NOT NULL,detailed BOOLEAN NOT NULL DEFAULT FALSE,enabled BOOLEAN NOT NULL DEFAULT TRUE,
 created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,UNIQUE(id,user_id),INDEX(user_id,enabled),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;
CREATE TABLE push_deliveries (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,subscription_id CHAR(36) CHARACTER SET ascii NOT NULL,notification_id BIGINT UNSIGNED NOT NULL,
 status ENUM('PENDING','SENT','FAILED','EXPIRED','CANCELLED') NOT NULL DEFAULT 'PENDING',attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,next_attempt_at DATETIME(3) NOT NULL,
 error_code VARCHAR(64) CHARACTER SET ascii NULL,created_at DATETIME(3) NOT NULL,sent_at DATETIME(3) NULL,
 UNIQUE(subscription_id,notification_id),INDEX(status,next_attempt_at),
 FOREIGN KEY(subscription_id,user_id) REFERENCES push_subscriptions(id,user_id) ON DELETE CASCADE,
 FOREIGN KEY(notification_id) REFERENCES student_notifications(id) ON DELETE CASCADE
) ENGINE=InnoDB;
